	@Test
	void partialPairsAreChunkedAndSurviveMutationAndReopen() throws Exception {
		try (TripleStore store = open("sp,op,psoc,posc")) {
			store.startTransaction();
			for (int i = 0; i < 65; i++) {
				int predicate = 100 + (i * 17) % 65;
				store.storeTriple(11, predicate, 33, 0, true);
				store.storeTriple(22, predicate, 44, 55, false);
			}
			store.commit();
			for (String index : List.of("sp", "op")) {
				for (boolean explicit : new boolean[] { true, false }) {
					assertEquals(65, pairs(store, index, explicit));
					assertTrue(store.getLmdbStats().get(index + index + (explicit ? "" : "-inf")).entries() < 65,
							"multiple pairs must share each physical chunk");
				}
			}
			assertEquals(65, rows(store, 11, -1, -1, -1, true).size());
			assertEquals(65, rows(store, -1, -1, 44, -1, false).size());
			assertEquals(Set.of(), rows(store, 10, -1, -1, -1, true));
			assertEquals(Set.of(), rows(store, 12, -1, -1, -1, true));
			for (int predicate : new int[] { 100, 132, 164 }) {
				remove(store, 11, predicate, 33, 0, true);
			}
			assertEquals(62, rows(store, 11, -1, -1, -1, true).size());
			store.startTransaction();
			assertFalse(store.storeTriple(11, 131, 33, 0, true));
			store.storeTriple(11, 132, 33, 0, true);
			store.rollback();
		}
		try (TripleStore store = open(null)) {
			assertEquals(62, rows(store, -1, -1, 33, -1, true).size());
			assertEquals(65, rows(store, 22, -1, -1, 55, false).size());
			remove(store, -1, -1, -1, -1, true);
			remove(store, -1, -1, -1, -1, false);
			for (String index : List.of("sp", "op")) {
				assertEquals(0, store.getLmdbStats().get(index + index).entries());
				assertEquals(0, store.getLmdbStats().get(index + index + "-inf").entries());
			}
		}
	}

	@Test
	void deletingOneSupporterPreservesPair() throws Exception {
		try (TripleStore store = open("SP,OP,PSOC,POSC")) {
			store.startTransaction();
			store.storeTriple(11, 22, 33, 0, true);
			store.storeTriple(11, 22, 44, 55, true);
			store.storeTriple(66, 22, 33, 55, true);
			store.commit();
			assertEquals(Set.of("[11, 22, 33, 0]", "[11, 22, 44, 55]"), rows(store, 11, -1, -1, -1, true));
			assertEquals(2, rows(store, -1, -1, 33, -1, true).size());
			assertEquals(2, pairs(store, "sp", true));
			assertEquals(2, pairs(store, "op", true));
			remove(store, 11, 22, 33, 0, true);
			assertEquals(1, rows(store, 11, -1, -1, -1, true).size());
			assertEquals(1, rows(store, -1, -1, 33, -1, true).size());
			assertEquals(2, pairs(store, "sp", true));
			assertEquals(2, pairs(store, "op", true));
			remove(store, 11, -1, -1, -1, true);
			assertEquals(Set.of(), rows(store, 11, -1, -1, -1, true));
			assertEquals(1, pairs(store, "sp", true));
			assertEquals(1, pairs(store, "op", true));
			remove(store, -1, -1, -1, -1, true);
			assertEquals(0, pairs(store, "sp", true));
			assertEquals(0, pairs(store, "op", true));
		}
	}

	@Test
	void promotionAndRollbackKeepStatementKindsSeparate() throws Exception {
		try (TripleStore store = open("psoc,posc,sp,op")) {
			store.startTransaction();
			store.storeTriple(11, 22, 33, 0, false);
			store.storeTriple(11, 22, 44, 55, false);
			store.commit();
			store.startTransaction();
			store.storeTriple(11, 22, 33, 0, true);
			store.commit();
			assertEquals(1, pairs(store, "sp", false));
			assertEquals(Set.of("[11, 22, 44, 55]"), rows(store, 11, -1, -1, -1, false));
			store.startTransaction();
			store.storeTriple(11, 22, 44, 55, true);
			store.rollback();
			assertEquals(1, rows(store, 11, -1, -1, -1, false).size());
			store.startTransaction();
			store.storeTriple(11, 22, 44, 55, true);
			store.commit();
			assertEquals(0, pairs(store, "sp", false));
			assertEquals(0, pairs(store, "op", false));
			assertEquals(2, rows(store, 11, -1, -1, -1, true).size());
		}
	}

